(function(){
  'use strict';
  const E=window.TraceEngine, $=s=>document.querySelector(s);
  const icons={
    grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
    layers:'<path d="m12 3 10 6-10 6L2 9l10-6Z"/><path d="m2 13 10 6 10-6M2 17l10 6 10-6"/>',
    link:'<path d="m10 13 4-4m-6 6-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m0 2 2-2a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0" transform="translate(2 1)"/>',
    book:'<path d="M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4V4Zm16 0h-4a3 3 0 0 0-3 3v14a4 4 0 0 1 4-2h3V4Z"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m7 10 5 5 5-5"/>',
    search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',
    arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',arrowUp:'<path d="M6 18 18 6M6 6h12v12"/>',
    check:'<path d="m5 12 4 4L19 6"/>',circleCheck:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',
    warning:'<path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v4m0 3v.2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.2"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
    device:'<rect x="6" y="2" width="12" height="20" rx="2.5"/><path d="M10 5h4m-3 14h2"/>',
    server:'<rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6.5h.1M7 17.5h.1m4-11h6m-6 11h6"/>',
    globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',
    file:'<path d="M14 3H5v18h14V8l-5-5Z"/><path d="M14 3v5h5M8 12h8m-8 4h5"/>',
    upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5"/>',
    bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-8l1-7Z"/>',
    shield:'<path d="m12 2 8 3v7c0 5-8 10-8 10S4 17 4 12V5l8-3Z"/><path d="m8 11 3 3 5-6"/>',
    close:'<path d="m6 6 12 12M6 18 18 6"/>',dots:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',
    refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 12-1l2 6M4 12l2 6a7 7 0 0 0 12-1"/>',
    fingerprint:'<path d="M7 8a6 6 0 0 1 10 0m-13 4a8 8 0 0 1 16 0m-11 0a3 3 0 0 1 6 0c0 5-2 8-2 8M6 12c0 4-1 6-1 6m7-6c0 5-2 9-2 9m8-9c0 4-1 7-1 7"/>',
    code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5M14 4l-4 16"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
    target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
    spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',
    copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',
    route:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M7 5h8a4 4 0 0 1 0 8H9a4 4 0 0 0 0 8h5"/>',
    minus:'<circle cx="12" cy="12" r="9"/><path d="M8 12h8"/>'
  };
  const icon=(name,cls='')=>`<svg aria-hidden="true" viewBox="0 0 24 24"${cls?` class="${cls}"`:''}>${icons[name]||icons.file}</svg>`;
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num=v=>Number(v).toLocaleString('en-US');
  const fixtures=window.TraceEvidenceCases||[];
  if(!fixtures.length){$('#app').textContent='未加载真实证据包，请先运行官方 CLI 采集脚本。';return}
  const primary=fixtures.find(x=>x.data.clientSalvage?.status==='ready')||fixtures.find(x=>x.key==='timeout-499')||fixtures[0];
  const state={page:'agent',key:primary.key,data:E.copy(primary.data),tab:'overview',filter:'all',search:'',expanded:false,mobile:false,imported:[],problem:'圈子首页请求报 5 秒超时，帮我关联客户端与服务端证据，确认下一步该查哪里。',draftTrace:'',draftLogs:'',run:null,saved:[],composerOpen:false};
  let result=E.analyze(state.data),lastFocus,toastTimer,connectionTimer,renderedProfileKey;
  const live={available:false,canQuery:false,connections:null,user:null};
  const sourceIcon=s=>({monitor:'bolt',runtime:'device',gateway:'globe',server:'server',client:'code',salvage:'device',review:'book',business:'check'}[s]||'file');
  const statusLabel=s=>({matched:'请求证据',context:'上下文',candidate:'待确认',excluded:'已排除'}[s]);
  const statusIcon=s=>({matched:'circleCheck',context:'layers',candidate:'clock',excluded:'minus'}[s]);
  const real=()=>['real-snapshot','real-query'].includes(state.data.provenance);
  const provenance=()=>state.data.provenance==='real-query'?'本次在线查询':real()?'真实采集快照':'用户导入 · 来源未核验';
  const time=s=>String(s||'未提供').replace('T',' ').replace('+08:00','');
  const safeUrl=s=>{try{const u=new URL(s);return u.protocol==='https:'&&u.hostname==='tracker.devops.xiaohongshu.com'?u.href:''}catch{return''}};
  const sourceLink=(label='APM 原始入口')=>{const u=safeUrl(state.data.collection?.sourceUrl);return u?`<a class="btn" href="${esc(u)}" target="_blank" rel="noopener noreferrer">${icon('arrowUp')}${label}</a>`:''};
  function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),3000)}
  function download(name,text,type='text/plain;charset=utf-8'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('已导出 '+name)}
  function allCases(){return [...state.imported.slice().reverse(),...state.saved,...fixtures].filter((x,i,a)=>a.findIndex(y=>(y.data.incident.traceId||y.key)===(x.data.incident.traceId||x.key))===i)}
  function setCase(key){const f=allCases().find(x=>x.key===key);if(!f)return;Object.assign(state,{key,data:E.copy(f.data),tab:'overview',filter:'all',search:'',page:'workbench',expanded:false,mobile:false,draftTrace:'',problem:f.data.investigation?.question||'圈子首页请求报 5 秒超时，帮我关联客户端与服务端证据，确认下一步该查哪里。'});render();window.scrollTo({top:0,behavior:'smooth'})}
  function userAvatarUrl(){try{const u=new URL(live.user?.avatar||'');return u.protocol==='https:'&&u.hostname&&!u.username&&!u.password?u.href:''}catch{return''}}
  function profile(){return `<div class="profile"><div class="avatar"><span>${esc((live.user?.name||'迹').slice(0,1))}</span>${userAvatarUrl()?`<img class="profile-avatar" data-user-avatar src="${esc(userAvatarUrl())}" alt="${esc(live.user?.name||'当前账号')}的头像" referrerpolicy="no-referrer">`: ''}</div><div><div class="profile-name">${esc(live.user?.name||'公司工作空间')}</div><div class="profile-caption">${live.user?'已通过公司 SSO 登录':'进入后自动识别登录身份'}</div></div></div>`}
  function sidebar(){return `<aside class="sidebar ${state.mobile?'open':''}" aria-label="主导航"><div class="brand"><img src="/assets/favicon.svg" alt="迹线标志"><div><div class="brand-name">迹线<span>Trace</span></div><div class="brand-sub">异常证据助手</div></div></div><div class="workspace-label">${icon('layers')}<span>跨平台排障工作空间</span></div><nav class="primary-navigation">${[['agent','spark','Agent 调查'],['workbench','target','调查工作台'],['library','layers','共享案件'],['sources','link','数据源与审计']].map(([p,i,n])=>`<button class="nav-item ${state.page===p?'active':''}" data-action="page" data-page="${p}">${icon(i)}${n}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="nav-item nav-help" data-action="help">${icon('book')}排查说明${icon('arrowUp')}</button>${profile()}</div></aside>`}
  function header(){return `<header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="展开导航">${icon('menu')}</button><div class="breadcrumb">工作空间${icon('chevron')}<strong>${({agent:'Agent 调查',workbench:'调查工作台',library:'共享案件',sources:'数据源与审计'})[state.page]}</strong></div><span class="spacer"></span><button class="icon-btn" data-action="help" aria-label="排查说明">${icon('info')}</button><span class="pill green"><span class="dot"></span>${state.page==='agent'?'真实数据查询':provenance()}</span><span class="top-caption">${state.page==='agent'?'多轮调查':state.data.provenance==='real-query'?'工作空间共享':'示例案件'}</span></header>`}
  function intro(title,subtitle,eyebrow='REAL EVIDENCE / CIRCLES'){return `<div class="intro"><div><div class="eyebrow"><span class="dot"></span>${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="intro-actions"><button class="btn" data-action="connections">${icon('link')}连接数据源</button>${sourceLink()}<button class="btn dark" data-action="report">${icon('file')}生成报告</button></div></div>`}
  function provenanceStrip(){return `<div class="provenance-strip"><div class="row">${icon('shield')}<span>${real()?'已通过官方 CLI 采集':'用户导入文件'} · ${esc(time(state.data.collection?.capturedAt))}</span></div><button class="text-btn" data-action="queries">查看采集记录 ${icon('arrowUp')}</button></div>`}
  function sampleBar(){return `<form class="sample-bar" id="sample-form"><label class="input-label" for="sample-id">${icon('fingerprint')}异常样本</label><div class="sample-input"><input id="sample-id" aria-label="APM 链接或 Trace ID" value="${esc(state.data.incident.traceId||state.data.incident.id)}" placeholder="粘贴 Trace ID，自动定位并查询链路" autocomplete="off" required></div><button type="submit" class="btn primary">${icon('search')}自动查询</button><details class="search-advanced"><summary>高级选项</summary><div class="search-advanced-panel"><label for="sample-time">发生时间（可选 · 北京时间）</label><input type="datetime-local" id="sample-time" aria-label="异常发生时间（可选，北京时间）" step="1"><p>填写后只查前后 5 分钟。留空则自动定位 Trace；未知样本检索最近 7 天。</p></div></details></form><div class="checks-strip"><div class="row">${icon('info')}只需 Trace ID · 自动定位时间，实时查询证据</div><div class="row warn">${icon('shield')}脱敏案件对公司登录用户共享</div><button type="button" data-action="conditions">查看条件边界 ${icon('chevron')}</button></div>${state.data.collection?.timeResolution?`<div class="time-resolution">${icon('clock')}<span>时间定位：${esc(state.data.collection.timeResolution.description)} · 实际检索 ${state.data.collection.timeResolution.searchedWindows.length} 个窗口 · 样本时间 ${esc(state.data.incident.occurredAt)}</span></div>`:''}`}
  function metrics(){const i=state.data.incident;return `<div class="metrics"><div class="metric unit"><div class="metric-label">${icon('clock')}${i.durationMs==null?'错误文案中的超时阈值':'客户端点位实测耗时'}</div><div class="metric-line"><span class="metric-value">${i.durationMs!=null?num(i.durationMs):i.timeoutThresholdMs?num(i.timeoutThresholdMs):'—'}</span><span class="metric-unit">ms</span><span class="metric-note">${i.durationMs==null?'非实测耗时':'duration 原值'}</span></div></div>${[['layers','会话上下文',result.contexts.length,'仅同会话'],['link','请求链路证据',result.matched.length,'含选定 HTTP 点位'],['shield','已排除的记录',result.excluded.length,'不属于本次 Trace']].map(([ic,n,count,note])=>`<div class="metric"><div class="metric-label">${icon(ic)}${n}</div><div class="metric-line"><span class="metric-value">${String(count).padStart(2,'0')}</span><span class="metric-unit">条</span><span class="metric-note">${note}</span></div></div>`).join('')}</div>`}
  function chart(){const i=state.data.incident;const max=Math.max(i.timeoutThresholdMs||0,i.durationMs||0,...result.gateway.map(r=>r.durationMs||0),...result.server.map(r=>r.durationMs||0),1);const gateway=result.gateway[0];const row=(label,ic,r,kind,missing)=>`<div class="timing-row"><div class="timing-label">${icon(ic)}${label}</div><div class="track">${r&&r.durationMs!=null?`<button class="bar ${kind}" style="width:${Math.max(2,Math.min(r.durationMs/max*100,100))}%" data-action="evidence" data-id="${esc(r.id)}" aria-label="查看${label}记录">${kind==='client'?num(r.durationMs)+' ms':''}${kind!=='client'?`<span class="bar-label">${num(r.durationMs)} ms</span>`:''}</button>`:`<div class="bar unknown" style="width:100%">${missing}</div>`}</div></div>`;
   return `<section class="section-pad"><div class="section-title"><span>实际观测到的耗时</span><div class="legend"><span><i style="background:#c7dbaa"></i>客户端</span><span><i style="background:#c9dbe5"></i>网关</span></div></div><div class="axis">${[0,.25,.5,.75,1].map(n=>`<span>${num(Math.round(max*n))}${n===1?' ms':''}</span>`).join('')}</div>${row('客户端','device',result.anchor,'client',`实测缺失 · duration 原值 ${esc(i.reportedDurationMs??'未提供')}`)}${row('接入层网关','globe',gateway,'gateway',state.data.downstream.gatewayQuerySuccess?'指定 Trace 查询返回 0 条':'尚未取得查询结果')}${row('业务服务端','server',result.server[0],'server','没有可用 Span，不展示虚构耗时')}<div class="chart-note">${icon('info')}<span>${i.durationMs==null?`“${esc(i.error)}”中的 ${esc(i.timeoutThresholdMs||'未知')} ms 是超时阈值。`:'网关 request_time 原值单位为秒，页面已转换为毫秒。'}不同端计时起点独立，无法据此相减归因网络。</span></div></section>`}
  function chain(){const i=state.data.incident;return `<div class="chain-map"><div class="chain-node active">${icon('device')}<strong>客户端 HTTP 点位</strong><span>${esc(i.error||'HTTP '+result.anchor.payload?.status)}</span><small>${esc(i.traceId?.slice(0,16)||'缺少 Trace')}…</small></div>${icon('arrow')}<div class="chain-node ${result.gateway.length?'active':'unavailable'}">${icon('globe')}<strong>接入层网关</strong><span>${result.gateway.length?num(result.gateway[0].durationMs)+' ms · Trace 一致':'查询未命中'}</span><small>${state.data.downstream.gatewayQuerySuccess?'已执行精确查询':'尚无有效查询结果'}</small></div>${icon('arrow')}<div class="chain-node ${result.server.length?'active':'unavailable'}">${icon('server')}<strong>业务服务端</strong><span>${result.server.length?'已关联 '+result.server.length+' 条 Span':state.data.downstream.spanCount===0?'未返回有效 Span':'未取得 Span'}</span><small>${result.server.length?'按同一 Trace 下钻':'无法判断处理耗时'}</small></div></div>`}
  function evidenceRank(r){if(r.id===state.data.incident.anchorRecordId)return 0;if(r.status==='matched'&&r.source==='gateway')return 1;if(r.status==='matched'&&r.source==='server')return 2;if(r.type==='client-log'&&r.payload?.networkMetrics)return 1.5;if(r.id==='REV-NATIVE-STAGES')return 1.6;if(r.id==='REV-GATEWAY-CHECK')return 1.7;if(r.type==='salvage-task')return 6;if(r.source==='salvage')return 3;const delta=Math.abs((r.timestamp||0)-(state.data.incident.timestamp||0));if(r.measurement==='infraJsError'&&delta<=100)return 3;if(r.measurement==='circle_home_stability'&&delta<=500)return 4;if(r.measurement==='paintTiming'&&delta<=5000)return 5;if(r.measurement==='hybridWhiteScreen'&&delta<=5000)return 6;return r.status==='excluded'?20:10}
  function filteredRecords(){const q=state.search.toLowerCase();return result.records.filter(r=>(state.filter==='all'||r.status===state.filter)&&(!q||[r.id,r.title,r.traceId,r.measurement,r.basis].join(' ').toLowerCase().includes(q))).sort((a,b)=>evidenceRank(a)-evidenceRank(b)||(a.timestamp||0)-(b.timestamp||0))}
  function evidenceRows(){const rows=filteredRecords();const visible=state.expanded?rows:rows.slice(0,5);return visible.length?visible.map(r=>`<tr data-action="evidence" data-id="${esc(r.id)}" tabindex="0" role="button" aria-label="查看证据 ${esc(r.id)}"><td><div class="evidence-title">${icon(sourceIcon(r.source))}${esc(r.title)}</div><div class="evidence-id">${esc(r.id)} · ${esc(r.measurement||E.sourceNames[r.source]||r.source)}</div></td><td><span class="status ${r.status}">${icon(statusIcon(r.status))}${statusLabel(r.status)}</span></td><td><span class="basis-compact">${esc(r.scope==='anchor'?'选定 HTTP 原始点位':r.scope==='trace'?'Trace + 接口 + 方法':r.scope==='session'?'仅同一会话':r.scope==='salvage-task'?'实际回捞任务，非请求行为':r.scope==='investigation-context'?'已核对上下文，非根因证明':r.scope==='client-log'?'日志包含同 Trace':'独立请求，排除归因')}</span></td><td>${icon('chevron')}</td></tr>`).join(''):`<tr><td colspan="4"><div class="empty">没有符合条件的记录</div></td></tr>`}
  function evidenceTable(){const rows=filteredRecords();return `<section class="evidence-section"><div class="evidence-toolbar"><h3>证据与上下文<span>${result.records.length}</span></h3><div class="filter" aria-label="筛选证据">${[['all','全部'],['matched','请求证据'],['context','上下文'],['excluded','已排除']].map(([k,n])=>`<button data-action="filter" data-filter="${k}" class="${state.filter===k?'active':''}" aria-pressed="${state.filter===k}">${n}</button>`).join('')}</div></div><label class="search-evidence">${icon('search')}<input id="evidence-search" value="${esc(state.search)}" placeholder="搜索点位、Trace ID 或证据编号" aria-label="搜索证据"></label><table class="evidence-table"><thead><tr><th>记录 / 来源</th><th>证据范围</th><th>关联依据</th><th></th></tr></thead><tbody id="evidence-rows">${evidenceRows()}</tbody></table><div id="expand-row">${rows.length>5?`<button class="expand-evidence" data-action="expand">${state.expanded?'收起':'展开全部 '+rows.length+' 条记录'} ${icon('down')}</button>`:''}</div><div class="evidence-footer">${icon('shield')}同一会话不等于同一次请求。对照记录不用于本次异常归因。</div></section>`}
  function timeline(){const records=result.records.filter(r=>r.source!=='gateway'&&r.source!=='server'&&!r.comparison&&(r.id===state.data.incident.anchorRecordId||r.sessionRef&&r.sessionRef===state.data.incident.sessionRef||r.type==='client-log'&&r.status==='matched'&&r.timestamp)).sort((a,b)=>(a.timestamp||0)-(b.timestamp||0));return `<section class="section-pad"><div class="section-title"><span>客户端会话原始时间线</span><span class="muted">按客户端点位时间排序</span></div>${records.map(r=>`<div class="timeline-item"><div class="timeline-icon">${icon(sourceIcon(r.source))}</div><div class="timeline-body"><div class="row between"><h4>${esc(r.title)}</h4><button class="evidence-link" data-action="evidence" data-id="${esc(r.id)}">${esc(r.id)} ↗</button></div><p><span class="mono">${esc(String(r.occurredAt||'').split(' ')[1]||r.occurredAt)}</span> · ${esc(r.measurement||r.type)}</p><p>${esc(eventDescription(r))}${r.status==='excluded'?' · 其他 Trace：不用于本次异常归因':''}</p></div></div>`).join('')}<div class="chart-note">${icon('info')}仅同一客户端会话的时间序列。网关使用独立时钟，不合并为跨端绝对时间线。</div></section>`}
  function eventDescription(r){const p=r.payload||{};if(r.type==='client-log')return p.networkMetrics?'原生网络实测 '+p.networkMetrics.callDuration+' ms；HTTP '+p.networkMetrics.httpCode+'，errorCode='+p.networkMetrics.errorCode:p.text?.split('\n')[0]||r.title;if(r.type==='http')return `status=${p.status??'未知'}，duration=${p.duration??'未提供'}，${p.errorMsg||'请求响应已记录'}`;if(r.measurement==='infraJsError')return p.errorMessage+'；'+p.errorExtra;if(r.measurement==='circle_home_stability')return `stage=${p.stage}，reason=${p.reason}，status=${p.status}`;if(r.measurement==='paintTiming')return `LCP=${p.largestContentfulPaint} ms，资源=${p.lcpUrl?.split('/').pop()||'未提供'}`;if(r.measurement==='rn_load_phase_track')return `${p.rnStage}，isSuccess=${p.isSuccess}，JS Engine=${p.container_jsEngine}`;if(r.measurement==='hybridWhiteScreen')return `errorType=${p.errorType}，ratio 原值=${p.ratio}`;return Object.entries(p).slice(0,4).map(([k,v])=>k+'='+v).join('，')}
  function raw(){return `<section class="section-pad"><div class="report-tools"><span class="muted small">脱敏后的真实采集快照</span><span class="spacer"></span><button class="btn" data-action="download-json">${icon('download')}下载 JSON</button></div><pre class="raw-code">${esc(JSON.stringify(state.data,null,2))}</pre></section>`}
  function investigation(){const i=state.data.incident;return `<div class="card"><div class="case-heading"><div class="row between"><h2>${esc(i.title)}</h2><span class="pill ${result.failed?'amber':'green'}"><span class="dot"></span>${result.failed?'根因证据待补':'独立正常对照'}</span></div><div class="case-id"><span>${esc(i.id)}</span><span>·</span><span>${esc(i.occurredAt)}</span></div><div class="case-meta"><span class="row">${icon('device')}${esc(i.platform||'未提供平台')}</span><span class="row">${icon('code')}${esc(i.bundle)}</span><span class="row">${icon('globe')}${esc(i.endpoint)}</span></div></div><div class="tabs" role="tablist" aria-label="证据视图">${[['overview','grid','证据总览'],['timeline','route','会话时间线'],['raw','code','原始记录']].map(([t,ic,n])=>`<button class="tab ${state.tab===t?'active':''}" data-action="tab" data-tab="${t}" role="tab" aria-selected="${state.tab===t}">${icon(ic)}${n}</button>`).join('')}<span class="spacer"></span><button class="text-btn" data-action="queries">采集记录 ${icon('arrowUp')}</button></div><div role="tabpanel">${state.tab==='overview'?chain()+chart()+evidenceTable():state.tab==='timeline'?timeline():raw()}</div></div>`}
  function insights(){const gateway=result.gateway[0],status=gateway?.payload?.response_status;let title,text;
   if(result.failed&&status===200){title='客户端报超时，<br>同 Trace 网关已有 200 记录。';text=`网关记录 ${num(gateway.durationMs)} ms。这不支持把客户端的 5 秒等待直接解释为网关处理慢，也不能证明客户端已收到响应。下一步核对响应到达与回调执行。`}
   else if(result.failed&&status===499){title='客户端报超时，<br>网关记录连接提前断开。';text=`网关记录 HTTP 499、${num(gateway.durationMs)} ms。提前断连是观测事实，断连发起方与原因仍需客户端取消记录、连接日志证明。`}
   else if(result.failed){title='超时是真实的，<br>下游证据仍待补齐。';text='客户端点位记录失败，但网关未匹配或查询未完成。保留实际执行状态，未命中不能证明请求没有到达服务端。'}
   else{title='客户端与网关记录已关联。';text='独立展示本次请求的 Trace、接口与方法。不同端计时不直接相减，也不将一次成功当作修复有效。'}
   return `<aside class="insights"><div class="insight-card"><div class="insight-eyebrow">${icon('spark')}真实证据支持的当前判断</div><h3>${title}</h3><p>${text}</p><span class="pill"><span class="dot"></span>已观测事实与根因分开</span></div><div class="side-card"><div class="side-title">${icon('circleCheck')}已确认事实<span>${result.facts.length}</span></div>${result.facts.map(f=>`<div class="fact"><h4>${esc(f.title)}</h4><p>${esc(f.text)}</p>${f.evidenceIds.map(id=>`<button class="evidence-link" data-action="evidence" data-id="${esc(id)}">${esc(id)} ↗</button>`).join('')}</div>`).join('')}</div><div class="side-card"><div class="side-title">${icon('target')}下一步最小排查动作<span>${result.gaps.length}</span></div>${result.gaps.slice(0,3).map(g=>`<div class="gap-box"><h4>${icon('warning')}${esc(g.title)}</h4><p>${esc(g.text)}</p></div>`).join('')}<button class="btn next-action" data-action="gaps">查看全部缺口与动作 ${icon('arrow')}</button></div><div class="boundary">${icon('shield')}<span>同一 Trace、同一会话与根因确认是不同证据范围。时间近不等于同一次请求。</span></div></aside>`}
  function verdictSummary(){const g=result.gateway[0],status=g?.payload?.response_status;return status===499?{title:'客户端报超时，网关记录提前断连',text:`同 Trace 网关 HTTP 499，耗时 ${g.durationMs} ms；断连原因仍待客户端记录验证。`}:status===200?{title:'客户端报超时，网关已记录 200',text:`网关耗时 ${g.durationMs} ms；尚不能证明响应到达客户端，需补充客户端网络记录。`}:{title:'已定位客户端异常，下游证据仍待补齐',text:'保留精确查询结果与缺口，未命中不能解释为请求没有到达服务端。'}}
  function questionComposer(){return `<section class="question-composer"><div class="composer-title"><span>${icon('spark')}圈子接口超时 · 自动关联证据</span><span class="pill">超时调查 Demo</span></div><p class="composer-scope">当前支持 circles 接口超时调查。请提供 Trace ID、超时监控链接，或包含 Trace 的日志；纯文字问题及白屏等场景尚不支持自动排查。</p><form id="sample-form"><textarea id="sample-question" aria-label="描述排查问题" placeholder="描述这次接口超时，并粘贴 Trace ID 或 APM 超时监控链接…">${esc(state.problem)}</textarea><div class="composer-context"><label class="trace-field">${icon('fingerprint')}<input id="sample-id" aria-label="APM 链接或 Trace ID" value="${esc(state.draftTrace)}" placeholder="Trace ID 或 APM 超时链接（也可写在问题或日志中）" autocomplete="off"></label><details class="search-advanced"><summary>补充日志与时间 ${icon('down')}</summary><div class="search-advanced-panel"><label for="sample-logs">补充日志（仅作为调查线索）</label><textarea id="sample-logs" aria-label="补充日志" placeholder="粘贴错误堆栈或相关日志">${esc(state.draftLogs)}</textarea><label class="log-file-label">${icon('upload')}导入文本日志<input id="log-file" type="file" accept=".txt,.log,.json" aria-label="导入文本日志"></label><label for="sample-time">发生时间（可选 · 北京时间）</label><input type="datetime-local" id="sample-time" aria-label="异常发生时间（可选，北京时间）" step="1"><p>默认自动定位 Trace。陌生 Trace 检索最近 7 天；指定时间后查询前后 5 分钟。</p></div></details></div><div class="composer-bottom"><div class="source-chips"><span><i class="dot"></i>APM</span><span><i class="dot"></i>XRAY</span><span><i class="dot"></i>Vesta</span></div><span class="composer-caption">个人授权查询 · 案件共享</span><button type="submit" class="btn primary" ${state.run?.running?'disabled':''}>${icon(state.run?.running?'clock':'arrow')}${state.run?.running?'正在调查':'开始排查'}</button></div></form></section>`}
  function runProgress(){if(!state.run)return '';return `<details class="run-progress-card" ${state.run.running||state.run.error?'open':''}><summary><strong>${state.run.running?'正在执行本次调查':state.run.error?'本次查询需要处理':'本次查询已完成'}</strong><span class="pill ${state.run.error?'amber':'green'}">${state.run.error?'查看失败原因':state.run.running?'执行中':'展开执行记录'}</span></summary>${state.run.steps.map(step=>`<div class="run-step">${icon('check')}<div>${esc(step.title)}<small>${esc(time(step.at))}</small></div></div>`).join('')}${state.run.error?`<div class="warning-inline">${esc(state.run.error)}</div>`:''}</details>`}
  function investigationFeed(){const v=verdictSummary(),vesta=state.data.clientSalvage;return `<section class="investigation-feed"><div class="panel-label"><span>${icon('route')}调查过程</span><span>${state.data.queries.length} 次实际工具调用</span></div><article class="agent-message"><div class="agent-avatar">${icon('spark')}</div><div><div class="agent-name">迹线 <span>调查摘要 · 基于已采集证据</span></div><p>核对客户端异常、网关与服务端链路；当现有证据无法解释超时时，补查客户端本地日志。</p><div class="investigation-plan"><span>${icon('check')}定位异常</span><span>${icon('check')}关联链路</span><span>${icon(vesta?.status==='ready'?'check':'clock')}${esc(salvageStatus(vesta))}</span><span>${icon('file')}留存证据</span></div></div></article><article class="finding-card"><div class="eyebrow">CURRENT FINDING</div><h2>${esc(v.title)}</h2><p>${esc(v.text)}</p><div class="evidence-citations">${[result.anchor,...result.gateway].map(r=>`<button data-action="evidence" data-id="${esc(r.id)}">${icon('file')}${esc(r.id)}</button>`).join('')}</div></article><div class="feed-section-title">已执行的查询 <button class="text-btn" data-action="queries">完整审计 ${icon('arrowUp')}</button></div><div class="audit-feed">${state.data.queries.map(q=>`<details class="audit-feed-item"><summary><span class="tool-badge ${esc(q.tool)}">${esc(q.tool.toUpperCase())}</span><span class="audit-title">${esc(q.title)}<small>${esc(time(q.queriedAt))}</small></span><span class="audit-result ${q.success?'':'warn'}">${q.success?q.returnedCount!=null?q.returnedCount+' 条':'已执行':'查询失败'}${icon('down')}</span></summary><div class="audit-details"><p>${q.success?'查询已执行，返回数量不代表根因确认。':esc(q.error||'查询失败，不作为空结果。')}</p><pre>${esc(JSON.stringify(q.scope,null,2))}</pre><p class="mono">${esc(q.id)} · SHA-256 ${esc(q.responseSha256)}</p></div></details>`).join('')}</div><div class="feed-section-title">接下来需要什么</div><div class="next-actions">${result.gaps.slice(0,3).map((g,j)=>`<article><span>0${j+1}</span><div><strong>${esc(g.title)}</strong><p>${esc(g.text)}</p></div></article>`).join('')}</div><button class="text-btn" data-action="gaps">查看全部证据缺口 ${icon('arrow')}</button></section>`}
  function clientPhaseSummary(){const m=clientMetrics();if(!m)return '';const clock=n=>new Date(n+28800000).toISOString().slice(11,23);return `<section class="client-phase-summary"><h3>本次客户端请求的关键时刻</h3><div class="client-phase-events">${[[m.trace.firstInterceptorStart,'进入首个拦截器','firstInterceptorStart'],[m.trace.requestStart,'请求阶段开始','requestStart'],[m.requestCallEndTimestamp,'请求结束','errorCode='+m.errorCode+' · hasResponse='+m.trace.hasResponse]].filter(([at])=>Number.isFinite(at)&&at>0).map(([at,label,field])=>`<div><time>${esc(clock(at))}</time><strong>${esc(label)}</strong><span>${esc(field)}</span></div>`).join('')}</div><p>${Number.isFinite(m.trace.fetchStart)&&m.trace.fetchStart>0?'进入拦截器至 fetchStart '+esc(m.trace.fetchStart-m.trace.firstInterceptorStart)+' ms；fetchStart 至请求阶段开始 '+esc(m.trace.requestStart-m.trace.fetchStart)+' ms':'进入拦截器至请求阶段开始 '+esc(m.trace.requestStart-m.trace.firstInterceptorStart)+' ms'}；callDuration=${esc(m.callDuration)} ms。阶段间隔不直接等同于排队或网络耗时。</p></section>`}
  function salvagePanel(){const s=state.data.clientSalvage;if(!s)return `<div class="salvage-empty">${icon('device')}<h3>客户端日志尚未补查</h3><p>Vesta 用于查找已有回捞任务、核对日志覆盖时间，并按需发起普通日志回捞。</p><button class="btn" data-action="salvage">${icon('search')}查询 / 回捞客户端日志</button><p class="small muted">关联目标来自当前异常样本，新增任务保留实际状态。</p></div>`;return `<section class="salvage-panel"><div class="row between"><h3>Vesta 客户端日志</h3><span class="pill ${s.status==='ready'?'green':'amber'}">${esc(s.statusLabel||s.status)}</span></div><p class="salvage-summary">${esc(s.summary||'已执行真实查询，详见任务记录。')}</p><dl class="salvage-meta">${[['任务 ID',s.taskId||'未创建'],['采集时间',time(s.queriedAt)],['日志覆盖',s.coverage?.description||'尚未取得覆盖范围'],['关联依据',s.associationBasis||'未取得可关联的请求记录']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${clientPhaseSummary()}${(s.excerpts||[]).map(x=>`<details class="log-excerpt"><summary><strong>${esc(x.title||'日志片段')}</strong><span>${esc(time(x.occurredAt))}</span>${icon('down')}</summary><p>${esc(x.association||'候选上下文')}</p><p class="mono">${esc(x.file)}:${esc(x.lineStart)}${x.lineEnd?'–'+esc(x.lineEnd):''}</p><pre>${esc(x.text)}</pre><small class="mono">SHA-256 ${esc(x.fileSha256)}</small></details>`).join('')}${(s.gaps||[]).map(g=>`<div class="warning-inline">${esc(typeof g==='string'?g:g.text)}</div>`).join('')}<div class="row" style="margin-top:20px"><button class="btn" data-action="salvage">${icon('refresh')}更新回捞状态</button><a class="btn" href="https://vesta.devops.xiaohongshu.com/xhs/log/log-salvage" target="_blank" rel="noopener noreferrer">Vesta 原始入口 ${icon('arrowUp')}</a></div></section>`}
  function clientMetrics(){
    const s=state.data.clientSalvage,m=s?.networkMetrics;
    if(!m||s.traceId!==state.data.incident.traceId||!(s.excerpts||[]).some(x=>x.traceId===state.data.incident.traceId))return null;
    const trace=(m.httpTraces||[]).find(x=>x.xrayTraceId===state.data.incident.traceId&&x.path===state.data.incident.endpoint&&x.method===state.data.incident.method);
    return trace&&Number.isFinite(m.callDuration)&&m.callDuration>=0&&Number.isFinite(trace.requestStart)&&trace.firstInterceptorStart>0?{...m,trace}:null;
  }
  function salvageStatus(s){return !s?'尚未补查':s.excerpts?.length?'已取得同 Trace 日志':s.downloadedFileCount?'已下载，未匹配':s.task?.hasLog?'已上传，待核对':s.status==='pending'?'等待上传':s.statusLabel||'尚未取得'}
  function evidenceCitations(ids){return ids.map(id=>`<button class="evidence-link" data-action="evidence" data-id="${esc(id)}">${icon('file')}${esc(id)} ↗</button>`).join('')}
  function historyRange(round){if(round.sourceKind==='business-feedback')return round.reportedOn+'（反馈日期，生效时间未提供）';const start=time(round.startedAt),end=time(round.lastQueryAt);return start===end?start:start+' — '+(start.slice(0,10)===end.slice(0,10)?end.slice(11):end)}
  function historyProgress(){const h=result.investigationHistory;if(!h?.rounds.length)return '';return `<button class="investigation-progress" data-action="show-detail" data-tab="history" aria-label="查看 ${h.rounds.length} 条排查与处理记录"><span class="history-progress-icon">${icon('route')}</span><span class="history-progress-copy"><strong>已记录 ${h.rounds.length} 次排查与处理<span>含业务确认</span></strong><span>${result.metricResolution?'已确认指标放大原因，过滤后趋势待观察':'从确认超时，推进到定位等待阶段'}</span></span><span class="history-progress-link">查看排查历史 ${icon('arrow')}</span></button>`}
  function historyPanel(){
    const h=result.investigationHistory;
    if(!h?.rounds.length)return `<section class="history-panel history-empty"><div class="history-panel-heading"><h3>排查历史</h3><p>当前案件尚未整理分轮结论。已有取证时间与执行结果保留在查询过程中。</p></div><button class="btn" data-action="show-detail" data-tab="process">查看查询过程 ${icon('arrow')}</button></section>`;
    return `<section class="history-panel" aria-labelledby="history-title"><div class="history-panel-heading"><div><span class="review-eyebrow">调查如何推进</span><h3 id="history-title">排查历史</h3></div><span class="pill">${esc(h.title)}</span></div><p class="history-explainer">${esc(h.description)}</p><div class="investigation-history">${h.rounds.map((round,n)=>`<details class="investigation-round ${n===h.rounds.length-1?'latest':''}" ${n===h.rounds.length-1?'open':''} data-round="${esc(round.id)}"><summary><span class="history-round-number">${String(n+1).padStart(2,'0')}</span><span class="history-round-heading"><span class="history-round-title">${esc(round.title)}${n===h.rounds.length-1?'<span class="history-latest-label">当前进展</span>':''}</span><span class="history-round-summary">${esc(round.summary)}</span><span class="history-round-time">${round.sourceKind==='business-feedback'?'业务反馈':'取证记录'} · ${esc(historyRange(round))}</span></span>${icon('down')}</summary><div class="history-round-body"><div class="history-finding"><h4>新增发现</h4><p>${esc(round.finding)}</p><div class="history-evidence-links">${evidenceCitations(round.evidenceIds)}</div></div><div class="history-conclusion"><h4>${round.sourceKind==='business-feedback'?'业务确认':'阶段判断'}<span>${round.sourceKind==='business-feedback'?'来源：用户反馈':'回溯整理'}</span></h4><p>${esc(round.conclusion)}</p></div><div class="history-advance">${icon('route')}<p>${esc(round.change)}</p></div><div class="history-remaining"><h4>${n===h.rounds.length-1?'下一步取证':'当轮未解决'}</h4><p>${esc(round.remaining)}</p></div><div class="history-audit-footer"><span>${round.sourceKind==='business-feedback'?'业务反馈已处理 · 趋势尚未验证':round.queries.length+' 条历史取证记录 · '+[...new Set(round.queries.map(q=>q.tool.toUpperCase()))].map(esc).join(' / ')}</span><button class="text-btn" data-action="history-audit" data-round="${esc(round.id)}">${round.sourceKind==='business-feedback'?'查看反馈来源':'查看取证记录'} ${icon('arrowUp')}</button></div></div></details>`).join('')}</div><p class="history-footnote">以上时间为工具取证时间，不是异常发生时间或结论生成时间。证据按钮打开当前案件留存记录，历史查询摘要按轮次保留。</p></section>`;
  }
  function historyAudit(id){const round=result.investigationHistory?.rounds.find(x=>x.id===id);if(!round)return;if(round.sourceKind==='business-feedback'){openModal('业务确认来源',`<p>来源：用户在本次对话中的业务处理反馈。</p><p>反馈日期：${esc(round.reportedOn)}。未提供实际生效时间。</p><blockquote class="business-feedback-quote">${esc(round.originalFeedback)}</blockquote><p>尚未取得过滤后趋势数据；本记录不计作工具查询。</p>`,`<button class="btn" data-action="close">返回排查历史</button>`);return;}openModal('历史取证 · '+esc(round.title),`<p>以下为本轮回溯所依据的原始取证摘要，保留实际时间、执行状态与响应哈希；本次查看不会重新执行查询。</p><div class="query-list">${round.queries.map(q=>`<article class="query-card"><div class="row between"><h3>${esc(q.title)}</h3><span class="pill ${q.success?'green':'amber'}">${q.success?'已执行':'查询失败'}</span></div><p>${esc(time(q.queriedAt))} · ${esc(q.tool.toUpperCase())} · ${esc(q.id)}</p>${q.error?`<p class="warning-inline">${esc(q.error)}</p>`:''}<details><summary>查询范围与响应摘要</summary><pre class="raw-code">${esc(JSON.stringify(q.scope||{},null,2))}</pre><p class="mono hash-line">SHA-256 ${esc(q.responseSha256||'未取得')}</p></details></article>`).join('')}</div>`,`<button class="btn" data-action="close">返回排查历史</button>`,true)}
  function reviewPanel(){
    const v=result.review,n=result.nativeStages;if(!v||!n)return '';
    const context=result.records.find(r=>r.id===v.contextEvidenceId)?.payload;
    const native=result.records.find(r=>r.id===v.nativeEvidenceId)?.payload;
    return `<section class="review-panel" aria-labelledby="review-title"><div class="review-heading"><div><span class="review-eyebrow">${result.metricResolution?'单次网络请求证据 · 不代表指标总量根因':'留存证据复核'}</span><h3 id="review-title">${result.metricResolution?'历史单次请求定位与判断边界':'当前定位与判断边界'}</h3></div><span class="pill amber">阶段已定位 · 根因待补证</span></div><div class="review-evidence-grid"><article class="review-evidence-card"><h4>原生阶段计时</h4><dl class="native-stage-list">${[['进入发送阶段前',n.beforeSendMs],['发送阶段',n.sendMs],['发送后至超时结束',n.afterSendMs]].map(([name,ms])=>`<div><dt>${esc(name)}</dt><dd>${esc(num(ms))}<small> ms</small></dd></div>`).join('')}</dl><p>另记录 session_wait=${esc(native?.session_wait)} ms，具体起止仍待核验。各阶段来自同一客户端计时，未与网关耗时相减。</p>${evidenceCitations([v.nativeEvidenceId])}</article>${context?`<article class="review-evidence-card"><div class="row between"><h4>同设备独立请求对照</h4><span class="pill">上下文</span></div><div class="review-context-numbers"><div><strong>${esc(context.requestCount)}</strong><span>条独立请求</span></div><div><strong>${esc(context.clientTimeoutCount)}</strong><span>条客户端超时</span></div></div><p>按请求开始时间：10:51:10–10:51:30。超时请求对应网关 ${esc(context.gateway200ForClientTimeout)} 条 200、${esc(context.gateway499ForClientTimeout)} 条 499、${esc(context.gateway400ForClientTimeout)} 条 400。</p><p>仅为该设备已下载样本；同设备异常不能直接证明本请求根因。</p>${evidenceCitations([v.contextEvidenceId,v.gatewayEvidenceId])}</article>`:''}</div><h4 class="review-subtitle">仍需验证的两个方向</h4><div class="hypothesis-grid">${v.hypotheses.map(h=>`<article class="hypothesis-card"><div class="row between"><h4>${esc(h.title)}</h4><span class="pill amber">${esc(h.state)}</span></div><p>${esc(h.text)}</p>${evidenceCitations(h.evidenceIds)}</article>`).join('')}</div><details class="review-boundary"><summary>${icon('info')}历史证据已补查，下一步需要完整 NetLog${icon('down')}</summary><div><p>${esc(v.boundary.text)}</p><ul>${v.boundary.requiredEvidence.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>云端补查的两条采样记录均非本次 Trace；Vesta 未发现额外附件。静默诊断默认模板为当前 HTTP 连通探测，未执行设备诊断。</p>${evidenceCitations([v.boundaryEvidenceId])}<div class="review-references">${v.references.filter(x=>/^https:\/\/docs\.xiaohongshu\.com\/doc\/[a-f0-9]{32}$/.test(x.url)).map(x=>`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)} ↗</a>`).join('')}</div></div></details><p class="review-provenance">复核于 ${esc(time(v.reviewedAt))} · 与原样本及日志哈希绑定。查询时间分别保留在审计中，留存复核不代表本次重新执行。</p></section>`
  }
  function metricConclusionView(){
    const m=result.metricResolution;
    return `<section class="conclusion-hero" aria-labelledby="conclusion-title"><div class="conclusion-main"><div class="conclusion-eyebrow"><span class="hero-dot"></span>当前结论<span class="hero-status">指标归因已确认</span></div><h1 id="conclusion-title">${esc(m.title)}</h1><p class="conclusion-description">${esc(m.summary)}</p><div class="conclusion-footer"><span>${esc(m.sourceLabel)} · ${esc(m.reportedOn)} · 效果待观察</span><button data-action="show-detail" data-tab="history">查看处理记录 ${icon('arrow')}</button></div></div><aside class="conclusion-next"><span class="next-label">下一步</span><h2>${esc(m.nextAction)}</h2><p>${esc(m.nextDetail)}</p><button class="btn" data-action="evidence" data-id="${esc(m.recordId)}">${icon('file')}查看业务确认 ${icon('arrow')}</button></aside></section>`;
  }
  function conclusionView(){
    if(result.metricResolution)return metricConclusionView();
    const i=state.data.incident,g=result.gateway[0],status=g?.payload?.response_status,s=state.data.clientSalvage;
    const m=clientMetrics(),observedTimeout=m?.errorCode===-1001&&m.trace.hasResponse===0,v=result.review,n=result.nativeStages;
    const title=v&&n?'原生发送前等待已定位，根因待补证':observedTimeout?'客户端约 5 秒超时，未收到响应':status===499?'网关记录连接提前断开，根因仍待确认':status===200?'网关已有 200 记录，客户端超时原因仍待确认':'客户端超时已确认，下游证据仍待补齐';
    const description=v&&n?`已确认原生发送前等待 ${n.beforeSendMs} ms，${m.callDuration} ms 后超时且未收到响应。同设备多个接口也超时，疑似网络链路或连接状态异常，具体原因仍待完整 NetLog 验证。`:observedTimeout?`同 Trace 客户端实测 ${m.callDuration} ms 后超时，未收到响应；${g?`网关记录 ${status}、${g.durationMs} ms。`:'网关证据仍待补齐。'}客户端早期阶段存在 ${m.trace.requestStart-m.trace.firstInterceptorStart} ms 间隔，具体等待原因仍待核对。`:status===499?`客户端报 5 秒超时，同 Trace 网关记录 499、耗时 ${g.durationMs} ms，显示连接提前结束。当前无法确认是服务端慢、客户端取消还是网络中断；下一步补齐客户端日志，核对超时、取消和断连的先后顺序。`:status===200?`同 Trace 网关记录 HTTP 200，耗时 ${g.durationMs} ms。客户端仍上报超时，尚不能确认响应是否到达，以及回调是否执行。`:'客户端已记录请求失败。指定范围内的网关查询未取得可用记录，不能据此判断请求没有到达服务端。';
    const action=v?'同版本复现并采集 NetLog':observedTimeout?'核对客户端早期等待阶段':status===499?'核对取消与断连记录':status===200?'核对响应到达与回调执行':'补充请求链路与客户端日志';
    return `<section class="conclusion-hero" aria-labelledby="conclusion-title"><div class="conclusion-main"><div class="conclusion-eyebrow"><span class="hero-dot"></span>当前结论<span class="hero-status">${v?'阶段已定位':'根因待确认'}</span></div><h1 id="conclusion-title">${esc(title)}</h1><p class="conclusion-description">${esc(description)}</p><div class="conclusion-footer"><span>${provenance()} · ${v?'已附留存复核 '+esc(time(v.reviewedAt)):esc(time(state.data.collection?.capturedAt))}${!v&&s?.excerpts?.length?' · 客户端补证 '+esc(time(s.queriedAt)):''}</span><button data-action="show-detail" data-tab="overview">查看判断依据 ${icon('arrow')}</button></div></div><aside class="conclusion-next"><span class="next-label">下一步</span><h2>${esc(action)}</h2><p>${v?'历史证据已补查；缺少请求到连接的绑定事件，仍需区分网络质量、会话等待和容灾分支。':observedTimeout?'已找到同 Trace 请求起止与网络指标。继续核对早期阶段定义、连接复用及等待记录，不能直接归因为排队或网络故障。':s?.taskId?`任务 ${esc(s.taskId)}：${esc(salvageStatus(s))}。${esc(s.coverage?.description||'覆盖范围未验证。')}`:'需要客户端网络层或回捞日志，才能进一步判断原因。'}</p><button class="btn" data-action="${v?'review-boundary':'show-detail'}" data-tab="${v?'overview':'salvage'}">${icon('device')}${v?'查看判断边界':s?.excerpts?.length?'查看客户端证据':s?.taskId?'查看回捞状态':'查看客户端证据'} ${icon('arrow')}</button></aside></section>`
  }
  function keyEvidenceCards(){
    const i=state.data.incident,g=result.gateway[0],s=state.data.clientSalvage,m=clientMetrics();
    return `<section class="key-evidence-grid" aria-label="三项关键证据"><button class="key-evidence-card" data-action="evidence" data-id="${esc(m?result.matched.find(r=>r.payload?.networkMetrics)?.id||result.anchor.id:result.anchor.id)}"><div class="key-card-label">${icon('device')}客户端异常${icon('arrowUp')}</div><div class="key-card-value">${m?esc(m.callDuration)+' <small>ms</small>':i.timeoutThresholdMs?esc(i.timeoutThresholdMs/1000)+' 秒超时':'请求失败'}</div><p>${m?'Vesta 网络层实测；APM 超时阈值 '+esc(i.timeoutThresholdMs)+' ms':i.timeoutThresholdMs?'错误文案中的阈值，实际请求耗时未取得':'按客户端原始点位记录展示'}</p><span class="key-card-source">${m?'Vesta · 网络总指标':'APM · '+esc(result.anchor.id)}</span></button><button class="key-evidence-card" ${g?`data-action="evidence" data-id="${esc(g.id)}"`:'data-action="show-detail" data-tab="overview"'}><div class="key-card-label">${icon('globe')}接入层网关${icon('arrowUp')}</div><div class="key-card-value">${g?esc(g.durationMs)+' <small>ms</small>':'未匹配'}${g?`<span class="key-http">HTTP ${esc(g.payload.response_status)}</span>`:''}</div><p>${g?'Trace、接口和方法一致；不能代替客户端耗时':'保留查询范围，未命中不代表请求未到达'}</p><span class="key-card-source">XRAY · ${g?esc(g.id):'查询结果'}</span></button><button class="key-evidence-card" data-action="show-detail" data-tab="salvage"><div class="key-card-label">${icon('file')}客户端日志${icon('arrowUp')}</div><div class="key-card-value status-value">${esc(salvageStatus(s))}<span class="key-pending-dot ${s?.excerpts?.length?'ready':''}"></span></div><p>${esc(s?.excerpts?.length?`${s.downloadedFileCount} 个明文文件 · ${s.excerpts.length} 条同 Trace 片段`:s?.coverage?.description||s?.summary||'按需通过 Vesta 获取客户端本地日志')}</p><span class="key-card-source">Vesta${s?.taskId?' · 任务 '+esc(s.taskId):''}</span></button></section>`
  }
  function processPanel(){return `<section class="process-panel"><div class="detail-intro"><h3>实际查询过程</h3><p>共 ${state.data.queries.length} 条工具记录。每条保留执行时间、查询范围和响应摘要，点击展开查看。</p></div><div class="audit-feed">${state.data.queries.map(q=>`<details class="audit-feed-item"><summary><span class="tool-badge ${esc(q.tool)}">${esc(q.tool.toUpperCase())}</span><span class="audit-title">${esc(q.title)}<small>${esc(time(q.queriedAt))}</small></span><span class="audit-result ${q.success?'':'warn'}">${q.success?q.returnedCount!=null?q.returnedCount+' 条':'已执行':'查询失败'}${icon('down')}</span></summary><div class="audit-details"><p>${q.success?'查询已执行，返回数量不代表根因确认。':esc(q.error||'查询失败，不作为空结果。')}</p><pre>${esc(JSON.stringify(q.scope,null,2))}</pre><p class="mono">${esc(q.id)} · SHA-256 ${esc(q.responseSha256)}</p></div></details>`).join('')}</div></section>`}
  function evidenceWorkspace(){return `<section id="details-workspace" class="card evidence-workspace"><div class="tabs" role="tablist" aria-label="排查详情">${[['overview','证据与依据'],['history','排查历史'],['salvage','客户端回捞'],['timeline','会话时间线'],['process','查询过程'],['raw','原始数据']].map(([t,n])=>`<button class="tab ${state.tab===t?'active':''}" data-action="tab" data-tab="${t}" role="tab" aria-selected="${state.tab===t}">${n}${t==='process'?`<span class="tab-count">${state.data.queries.length}</span>`:''}</button>`).join('')}</div>${state.tab==='overview'?`${reviewPanel()}<div class="detail-intro"><h3>支撑判断的原始证据</h3><p>先查看关键记录，其余上下文按需展开。任务状态、同一会话与同一次请求分别标注。</p></div>${evidenceTable()}`:state.tab==='history'?historyPanel():state.tab==='salvage'?salvagePanel():state.tab==='timeline'?timeline():state.tab==='process'?processPanel():raw()}</section>`}
  function workbench(){return `<div class="case-page-heading"><div><div class="case-page-kicker">超时调查 · circles</div><h2>圈子首页请求超时</h2><p>${esc(state.data.incident.occurredAt)}<span>·</span>${esc(state.data.incident.platform)}<span>·</span>${esc(state.data.incident.bundle)}</p></div><div class="case-heading-actions"><button class="btn" data-action="open-question">${icon('plus')}继续排查</button><button class="btn dark" data-action="report">${icon('download')}导出报告</button><button class="icon-btn" data-action="connections" aria-label="连接数据源">${icon('link')}</button></div></div>${conclusionView()}${result.metricResolution?'<p class="metric-resolution-scope">本次已处理的是 JS 指标统计口径；下方保留原始单次请求证据，网络超时原因单独核对。</p>':''}${historyProgress()}${keyEvidenceCards()}<section class="continue-investigation" id="question-panel" data-open="${state.composerOpen}"><button class="question-toggle" type="button" data-action="toggle-question" aria-expanded="${state.composerOpen}" aria-controls="question-content"><span>${icon('spark')}继续排查这个问题</span><span>补充问题、日志或新的 Trace ID ${icon('down')}</span></button><div class="question-content" id="question-content">${questionComposer()}</div></section><div id="run-progress">${runProgress()}</div>${state.data.collection?.saveError?`<div class="warning-inline">${esc(state.data.collection.saveError)}</div>`:''}${evidenceWorkspace()}<div class="case-bottom-meta"><span class="mono">Trace ${esc(state.data.incident.traceId)}</span><button class="text-btn" data-action="conditions">查看版本与环境边界 ${icon('arrowUp')}</button>${state.data.collection?.savedToAccount?'<span>已保存为共享案件</span>':''}</div>`}
  function library(){return `${intro('真实样本，独立核对。','查看工作空间内的共享调查结果，同一 Trace 保留最新案件入口。','REAL CASE LIBRARY')}<div class="info-banner">${icon('shield')}公司登录用户均可查看脱敏案件。发起查询时使用各自账号的授权，平台权限分别核验。</div><div class="library-grid">${allCases().map((f,j)=>`<article class="library-card"><div class="row between" style="width:100%"><div class="library-icon">${icon(j?'circleCheck':'clock')}</div><span class="pill green">${f.data.provenance==='real-snapshot'?'示例快照':f.data.provenance==='real-query'?'共享在线案件':'用户导入'}</span></div><h3>${esc(f.label)}</h3><p>${esc(f.caption)}</p><span class="mono">${esc(f.data.incident.traceId)}</span><button class="btn" data-action="case" data-key="${esc(f.key)}">打开排查工作台 ${icon('arrow')}</button></article>`).join('')}</div><div class="row" style="margin-top:22px"><button class="btn" data-action="import">${icon('upload')}导入新的证据包</button><button class="btn" data-action="queries">${icon('file')}查看采集过程</button></div>`}
  function queryCards(){return state.data.queries.map(q=>`<article class="query-card"><div class="row between"><h3>${esc(q.id)} · ${esc(q.title)}</h3><span class="pill ${q.success?'green':'amber'}">${q.success?'查询成功':'查询失败'}</span></div><p>${esc(q.queriedAt)} · ${esc(q.tool.toUpperCase())} · ${q.returnedCount==null?'数量未取得':'返回 '+q.returnedCount+' 条'}</p><pre class="raw-code">${esc(JSON.stringify(q.scope,null,2))}</pre><details><summary>查看可复现命令与响应摘要</summary><pre class="raw-code">${esc((q.command||[]).map(v=>/\s/.test(v)?JSON.stringify(v):v).join(' '))}</pre><p>用户与原始会话 ID 已移除。Request ID：<span class="mono">${esc(q.requestId||'工具未返回查询 Request ID')}</span></p><p class="mono hash-line">响应 SHA-256：${esc(q.responseSha256)}</p>${q.error?`<p class="warning-inline">${esc(q.error)}</p>`:''}${q.responseSummary?`<pre class="raw-code">${esc(JSON.stringify(q.responseSummary,null,2))}</pre>`:''}</details></article>`).join('')}
  function sources(){return `${intro('每条证据，都能找到来处。','保留查询范围、执行时间、退出状态与响应摘要，明确哪些数据没有取到。','ACQUISITION & PROVENANCE')}<div class="info-banner">${icon('shield')}${esc(real()?state.data.collection?.privacy:'用户导入内容未经来源核验，也未自动脱敏。仅在当前浏览器处理。')}</div><div class="source-grid"><article class="card source-card"><h3>官方 Vesta CLI</h3><p>按异常原始样本定位用户和平台，查询既有任务、发起普通日志回捞并核对实际覆盖。等待上传不等于已经取得日志。</p><div class="source-fields"><code>log list</code><code>log salvage</code><code>log download</code></div><button class="btn" data-action="salvage" style="margin-top:16px">查询当前案件客户端日志</button></article><article class="card source-card"><h3>官方 APM CLI</h3><p>已实际查询用户会话列表与完整会话点位；版本、错误与 HTTP 字段均来自返回数据。HTTP 与 JS 错误按同会话展示，未伪造请求级关联。</p><div class="source-fields"><code>log session list</code><code>log session detail</code><code>log search</code></div></article><article class="card source-card"><h3>官方 XRAY CLI</h3><p>通过客户端原始 Trace 查询服务端 Span 与接入层 rgw 日志。未命中保留为查询结果，查询失败单独显示，不解释为服务正常。</p><div class="source-fields"><code>trace tree</code><code>log query --table rgw</code></div></article></div><div class="provenance-explainer"><strong>预置案例与在线查询分别标记</strong><p>预置案例保留采集时刻；点击“自动查询”会调用官方 CLI 重新采集。首次需在“连接数据源”完成官方授权。公司登录用户均可查询，使用各自的官方平台授权；脱敏案件在工作空间共享，也可导出报告。</p></div><div class="row between" style="margin:24px 0 15px"><h3 style="font-size:15px">实际采集记录</h3><button class="btn" data-action="download-json">${icon('download')}导出含审计的证据包</button></div><div class="query-list">${queryCards()}</div>`}
  function render(){
    result=E.analyze(state.data);
    const app=$('#app'),profileKey=JSON.stringify([live.user?.name||'',userAvatarUrl()]);
    // Mount the shell once: recreating sidebar images on each state update causes a visible flash.
    if(!app.querySelector('.shell')){
      app.innerHTML=`<div class="shell">${sidebar()}<div class="main"></div></div>`;
      renderedProfileKey=profileKey;
    }
    const side=app.querySelector('.sidebar');
    side.classList.toggle('open',state.mobile);
    side.querySelectorAll('.primary-navigation [data-page]').forEach(button=>{
      const active=button.dataset.page===state.page;
      button.classList.toggle('active',active);
      if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');
    });
    // Refresh the profile only when the SSO identity actually changes; keep the brand image mounted.
    if(renderedProfileKey!==profileKey){side.querySelector('.profile').outerHTML=profile();renderedProfileKey=profileKey;}
    app.querySelector('.main').innerHTML=`${header()}<main class="content">${state.page==='agent'?window.TraceAgentUI.html():state.page==='workbench'?workbench():state.page==='library'?library():sources()}<footer class="page-footer"><span class="row">${icon('shield')}${state.page==='agent'?'依据平台实际返回分析 · 脱敏报告在工作空间共享':provenance()+' · '+(real()?'平台证据已脱敏':'未自动脱敏，仅本地处理')}</span><span class="mono">TRACE / EVIDENCE BEFORE CONCLUSIONS</span></footer></main>`;
  }

  function openModal(title,body,footer='',wide=false){lastFocus=document.activeElement;$('#overlay-root').innerHTML=`<div class="modal-backdrop" data-dismiss="true"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}" ${wide?'style="width:800px"':''}><div class="modal-header"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="关闭弹窗">${icon('close')}</button></div><div class="modal-content">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;document.body.classList.add('overlay-open');$('#overlay-root button, #overlay-root input')?.focus()}
  function closeOverlay(){clearInterval(connectionTimer);$('#overlay-root').innerHTML='';document.body.classList.remove('overlay-open');if(lastFocus&&document.contains(lastFocus))lastFocus.focus()}
  function openEvidence(id){const r=result.records.find(x=>x.id===id);if(!r)return;lastFocus=document.activeElement;const query=state.data.queries.find(q=>q.id===r.queryId);$('#overlay-root').innerHTML=`<div class="drawer-backdrop" data-dismiss="true"><section class="drawer" role="dialog" aria-modal="true" aria-label="原始证据 ${esc(r.id)}"><div class="modal-header"><span class="mono small">${esc(r.id)} / 脱敏原始记录</span><button class="icon-btn" data-action="close" aria-label="关闭证据详情">${icon('close')}</button></div><div class="drawer-body"><h3>${esc(r.title)}</h3><div class="row"><span class="pill ${r.status==='matched'?'green':r.status==='context'?'':'amber'}">${statusLabel(r.status)}</span><span class="pill">${provenance()}</span></div><p class="drawer-desc">${esc(eventDescription(r))}</p><div class="info-banner">${icon('fingerprint')}${esc(r.basis)}</div><dl>${[['来源',E.sourceNames[r.source]||r.source],['点位',r.measurement||r.type],['发生时间',r.occurredAt||'未提供'],['Trace ID',r.traceId||'未上报'],['Request ID',r.requestId||'未上报'],['请求接口',r.endpoint||'不适用'],['原始耗时',r.reportedDurationMs!=null?r.reportedDurationMs+' ms':r.durationMs!=null?r.durationMs+' ms（由原始秒值转换）':'未提供'],['采集查询',r.queryId||'未提供'],['查询时间',query?.queriedAt||'未提供']].map(([k,v])=>`<div class="kv"><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="drawer-label">真实返回字段（已脱敏）</div><pre class="raw-code">${esc(JSON.stringify(r.payload,null,2))}</pre><p class="bottom-note">${esc(state.data.collection?.recordIds||'证据编号由导入文件提供。')}<br>移除字段：${esc((r.omittedFields||[]).join(', ')||'无额外字段')}</p><div class="row" style="margin-top:16px"><button class="btn" data-action="copy-evidence" data-id="${esc(id)}">${icon('copy')}复制这条记录</button>${sourceLink()}</div></div></section></div>`;document.body.classList.add('overlay-open');$('#overlay-root button')?.focus()}
  function conditions(){openModal('运行条件与判断边界',`<p>“已采集版本”不等于“已对齐待验证版本”。后台查询环境 prod 也不能替代请求实际泳道。</p><div class="condition-grid">${result.checks.map(c=>`<div class="condition-row"><div class="row between"><strong>${esc(c.name)}</strong><span class="pill ${c.status==='pass'?'green':'amber'}">${({pass:'核对通过',fail:'存在差异',observed:'已观测，边界待核对',unknown:'未取得完整证据'})[c.status]}</span></div><p>实际：<span class="mono">${esc(c.actual)}</span></p><p>对照条件：${esc(c.expected)}</p></div>`).join('')}</div><div class="chart-note">${icon('info')}未提供代码提交、待验证版本和清缓存操作记录。本次样本不能证明某个修复已生效。</div>`,`<button class="btn" data-action="close">返回</button>`)}
  function gaps(){openModal('证据缺口与下一步动作',`<div class="condition-grid">${result.gaps.map(g=>`<div class="condition-row"><strong>${esc(g.title)}</strong><p>${esc(g.text)}</p></div>`).join('')}</div>`,`<button class="btn" data-action="close">返回工作台</button>${sourceLink()}`)}
  function queries(){openModal('实际采集记录',`<p>这些记录来自官方 CLI 的真实执行。保留成功 / 失败状态与响应哈希；在线查询保留本次实际执行记录，预置案例保留其历史采集记录。</p><div class="query-list">${queryCards()}</div>`,`<button class="btn" data-action="close">返回工作台</button><button class="btn primary" data-action="download-json">${icon('download')}导出证据包</button>`,true)}
  function reportModal(){openModal('真实排查上下文报告',`<p>包含实际观测、会话相关性、查询缺口和采集审计；没有证据的原因保持待验证。</p><div class="report-preview">${esc(E.report(result).split('## 原始证据快照')[0])}</div>`,`<button class="btn" data-action="copy-report">${icon('copy')}复制上下文</button><button class="btn primary" data-action="download-report">${icon('download')}导出完整报告</button>`,true)}
  function importModal(){openModal('导入结构化证据包',`<p>支持当前格式的 JSON 证据包。即使文件自称真实采集，导入后也会标记为“来源未核验”。数据只在当前浏览器内存中处理。</p><textarea id="json-input" spellcheck="false" aria-label="粘贴 JSON 证据包" placeholder="粘贴从当前快照导出的 JSON"></textarea><label for="json-file">选择 JSON 文件（最大 2 MB）</label><div class="upload-area">${icon('upload')}<input id="json-file" type="file" accept=".json,application/json" aria-label="上传 JSON 证据包"></div><div id="import-error" class="form-error" role="alert"></div>`,`<button class="btn" data-action="download-json">下载当前格式</button><span class="spacer"></span><button class="btn primary" data-action="confirm-import">校验并关联 ${icon('arrow')}</button>`)}
  function confirmImport(){try{const text=$('#json-input').value;if(text.length>2*1024*1024)throw new Error('证据包超过 2 MB。');const data=E.validate(JSON.parse(text));data.provenance='import';const key='import-'+Date.now();state.imported.push({key,label:data.incident.title,caption:'用户导入 · 未核验来源',data});closeOverlay();setCase(key);toast('已导入并按标识重新核对')}catch(e){$('#import-error').textContent=e instanceof SyntaxError?'JSON 格式不正确。':e.message}}
  function help(){if(state.page==='agent'){openModal('如何使用 Agent 调查','<p>直接描述问题，尽量附应用、发生时间、页面或接口。也可以粘贴官方 APM 链接、Trace ID 和日志。</p><ol class="help-list"><li>迹线先检查线索，选择已接入的数据源；缺少关键范围时会一次补问。</li><li>查询使用当前账号权限，APM 与 XRAY 首次使用需要本人授权。</li><li>每次查询保留执行状态与脱敏结果，结论中的编号可以展开查依据。</li><li>补充问题可继续同一调查，每轮结论和新证据都会留存。</li></ol><p>目前支持 APM、XRAY、Vesta 既有日志的只读调查。未接入的平台会明确说明。调查工作台保留原超时案例。</p>','<button class="btn primary" data-action="close">开始调查</button>');return}openModal('真实排查如何演示',`<ol class="help-list"><li>先看超时 + 网关 200、超时 + 网关 499、以及未匹配这三类真实样本。</li><li>打开会话时间线：核对 HTTP、JS 错误、稳定性与渲染记录的先后。</li><li>查看采集记录：分别核对每条样本的执行状态、返回数量与来源。</li><li>只粘贴 Trace ID 即可自动定位时间并在线查询；需要时在高级选项补充发生时间。</li><li>优先查看异常 HTTP、同 Trace 网关与相邻 JS 错误，其余上下文按需展开。</li><li>生成报告，保留真实缺口与下一步动作。</li></ol><div class="warning-inline" style="margin-top:15px">预置案例是已采集的真实快照；在线查询需先连接 APM 与 XRAY。汇总链接会先列出候选样本，选定后才查询链路。没有证据的环节保留缺口。</div>`,`<button class="btn primary" data-action="close">开始核对 ${icon('arrow')}</button>`)}
  async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制')}catch{toast('浏览器不允许复制，请使用导出文件')}}
  document.addEventListener('error',e=>{if(e.target.matches?.('img[data-user-avatar]'))e.target.remove()},true);
  document.addEventListener('click',async event=>{const t=event.target.closest('[data-action]');if(t){switch(t.dataset.action){case'toggle-question':state.composerOpen=!state.composerOpen;render();break;case'open-question':state.composerOpen=true;render();$('#question-panel')?.scrollIntoView?.({behavior:'smooth',block:'center'});$('#sample-question')?.focus({preventScroll:true});break;case'history-audit':historyAudit(t.dataset.round);break;case'review-boundary':{state.tab='overview';render();const boundary=$('.review-boundary');if(boundary){boundary.open=true;boundary.scrollIntoView?.({behavior:'smooth',block:'center'});}break;}case'show-detail':state.tab=t.dataset.tab;render();$('#details-workspace')?.scrollIntoView?.({behavior:'smooth',block:'start'});break;case'salvage':runSalvage();break;case'connections':connectionModal();break;case'retry-live':runLiveSearch();break;case'authorize':authorize(t.dataset.tool);break;case'choose-live':runInvestigation(t.dataset.token);break;case'page':if(state.page===t.dataset.page&&!state.mobile)break;state.page=t.dataset.page;state.mobile=false;render();break;case'case':setCase(t.dataset.key);break;case'tab':state.tab=t.dataset.tab;render();break;case'filter':state.filter=t.dataset.filter;state.expanded=false;render();break;case'expand':state.expanded=!state.expanded;render();break;case'evidence':openEvidence(t.dataset.id);break;case'conditions':conditions();break;case'gaps':gaps();break;case'queries':queries();break;case'close':closeOverlay();break;case'import':closeOverlay();importModal();break;case'confirm-import':confirmImport();break;case'help':help();break;case'report':reportModal();break;case'copy-report':await copy(E.report(result).split('## 原始证据快照')[0]);break;case'download-report':download('Trace-'+state.data.incident.id.replace(/[^a-zA-Z0-9_-]/g,'_')+'.md',E.report(result),'text/markdown;charset=utf-8');break;case'download-json':download('trace-real-evidence.json',JSON.stringify(state.data,null,2),'application/json');break;case'copy-evidence':await copy(JSON.stringify(state.data.records.find(r=>r.id===t.dataset.id),null,2));break;case'menu':state.mobile=!state.mobile;$('.sidebar').classList.toggle('open',state.mobile);break}}else if(event.target.dataset.dismiss==='true')closeOverlay();else if(state.mobile&&!event.target.closest('.sidebar')){state.mobile=false;$('.sidebar').classList.remove('open')}});
  document.addEventListener('submit',e=>{if(e.target.id==='sample-form'){e.preventDefault();runLiveSearch()}});
  document.addEventListener('input',e=>{if(e.target.id==='sample-question'){state.problem=e.target.value;const ids=[...new Set((e.target.value.match(/\b(?:[a-fA-F0-9]{32}|[a-fA-F0-9]{16})\b/g)||[]).map(x=>x.toLowerCase()))];if(ids.length===1){state.draftTrace=ids[0];if($('#sample-id'))$('#sample-id').value=ids[0]}}if(e.target.id==='sample-id')state.draftTrace=e.target.value;if(e.target.id==='sample-logs')state.draftLogs=e.target.value;if(e.target.id==='evidence-search'){state.search=e.target.value;state.expanded=true;$('#evidence-rows').innerHTML=evidenceRows();$('#expand-row').innerHTML=''}});
  document.addEventListener('change',async e=>{if(e.target.id==='log-file'){const f=e.target.files[0];if(f){if(f.size>512*1024){toast('文本日志请控制在 512 KB 以内。');return}state.draftLogs=await f.text();$('#sample-logs').value=state.draftLogs;}return}if(e.target.id==='sample-select')setCase(e.target.value);if(e.target.id==='json-file'){const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024){$('#import-error').textContent='文件超过 2 MB。';return}try{$('#json-input').value=await f.text()}catch{$('#import-error').textContent='读取文件失败。'}}});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeOverlay();state.mobile=false;$('.sidebar')?.classList.remove('open')}if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr[data-action]')){e.preventDefault();e.target.click()}if(e.key==='Tab'&&$('#overlay-root').children.length){const els=[...$('#overlay-root').querySelectorAll('button,input,textarea,select,a[href],summary')].filter(el=>!el.disabled);if(!els.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
  async function api(path,options={}){const response=await fetch('/api/'+path,{credentials:'same-origin',cache:'no-store',...options,headers:{'Content-Type':'application/json','X-Trace-Request':'1',...(options.headers||{})}});let data;try{data=await response.json()}catch{throw new Error('在线服务未返回有效结果，请刷新页面确认登录状态。')}if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:Array.isArray(data.detail)?data.detail.map(x=>x.msg).join('；'):'查询服务暂不可用，请稍后重试。');return data}
  async function probe(){try{const d=await api('capabilities');live.available=d.liveQuery;live.canQuery=d.canQuery;live.user=d.user||null;window.TraceAgentUI.setCapabilities(d);return d}catch{live.available=false;return null}}
  function authUrl(raw){try{const u=new URL(raw);return u.protocol==='https:'&&u.hostname.endsWith('.xiaohongshu.com')?u.href:''}catch{return''}}
  async function connectionModal(){await probe();if(!live.available){openModal('在线服务尚未就绪','<p>当前打开的是本地文件或静态版本。在线查询需要部署后的应用服务，不会用预置数据代替实际查询。</p>',`<button class="btn" data-action="close">返回</button>`);return}if(!live.canQuery){openModal('请先完成公司登录','<p>进入应用后将使用当前 SSO 身份。查询平台的首次授权需要由本人完成。</p>',`<button class="btn" data-action="close">返回</button>`);return}openModal('连接真实数据源',`<p>应用已自动识别你的公司 SSO 身份。APM / XRAY 首次使用需本人完成官方授权；Vesta 复用本次 SSO。各人的授权独立保存，查询按各自权限执行。</p><div id="connections-body" class="condition-grid">正在核对连接状态…</div><div id="connection-error" class="form-error" role="alert"></div>`,`<button class="btn" data-action="close">返回工作台</button><button class="btn primary" data-action="${state.page==='agent'?'close':'retry-live'}">${state.page==='agent'?'返回继续调查':'连接后继续查询'} ${icon('arrow')}</button>`);await refreshConnections();connectionTimer=setInterval(()=>{if(!$('#connections-body')){clearInterval(connectionTimer);return}refreshConnections()},2500)}
  async function refreshConnections(){if(!$('#connections-body'))return;try{const data=await api('connections');live.connections=data;const target=$('#connections-body');if(!target)return;target.innerHTML=['apm','xray'].map(tool=>{const auth=data.authorizations?.[tool],connected=data[tool]?.connected;const url=authUrl(auth?.url);const pending=auth?.state==='pending';return `<div class="condition-row"><div class="row between"><strong>${tool.toUpperCase()}</strong><span class="pill ${connected?'green':pending?'amber':''}">${connected?'当前账号已连接':pending?'等待官方授权':'未连接'}</span></div>${auth?.message?`<p>${esc(auth.message)}</p>`:''}${pending&&url?`<div class="authorization-link"><a class="btn primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">打开官方授权页 ${icon('arrowUp')}</a>${auth.code?`<span class="mono">授权码 ${esc(auth.code)}</span>`:''}<span class="muted small">授权码有效期以官方页面为准，过期后请重新发起。</span></div>`:!connected&&!pending?`<button class="btn" data-action="authorize" data-tool="${tool}" style="margin-top:10px">连接 ${tool.toUpperCase()}</button>`:''}</div>`}).join('')+`<div class="condition-row"><div class="row between"><strong>VESTA</strong><span class="pill">${data.vesta?.ssoAvailable?'当前 SSO 可用':'查询时核验 SSO'}</span></div><p>官方日志回捞 CLI · 使用当前账号查询。任务创建、客户端上传和日志覆盖分别记录。</p><a class="text-btn" href="https://vesta.devops.xiaohongshu.com/xhs/log/log-salvage" target="_blank" rel="noopener noreferrer">打开 Vesta</a></div>`}catch(e){if($('#connection-error'))$('#connection-error').textContent=e.message}}
  async function authorize(tool){try{await api('auth/'+tool+'/start',{method:'POST',body:'{}'});await refreshConnections()}catch(e){if($('#connection-error'))$('#connection-error').textContent=e.message}}
  async function waitJob(jobId,title){if(!state.run||!state.run.running)state.run={running:true,steps:[]};render();for(let count=0;count<600;count++){const data=await api('jobs/'+jobId);state.run.steps=data.steps||[];if($('#run-progress'))$('#run-progress').innerHTML=runProgress();if(data.state==='error'){state.run.running=false;state.run.error=data.error||'查询失败';render();throw new Error(state.run.error)}if(data.state==='complete'){state.run.running=false;if($('#run-progress'))$('#run-progress').innerHTML=runProgress();return {result:data.result,elapsedSeconds:data.elapsedSeconds}}await new Promise(r=>setTimeout(r,1000))}state.run.running=false;state.run.error='等待超时，可稍后核对任务状态。';render();throw new Error(state.run.error)}
  async function runLiveSearch(){const sample=[$('#sample-question')?.value,$('#sample-id')?.value,$('#sample-logs')?.value].filter(Boolean).join('\n').trim(),occurredAt=$('#sample-time')?.value;if(!sample){toast('请粘贴 Trace ID 或官方 APM 链接。');return}try{await probe();if(!live.available||!live.canQuery){await connectionModal();return}const c=await api('connections');live.connections=c;if(!c.apm?.connected||!c.xray?.connected){await connectionModal();return}clearInterval(connectionTimer);const started=await api('search',{method:'POST',body:JSON.stringify({sample,question:state.problem,...(occurredAt?{occurredAt}:{})})});const done=await waitJob(started.jobId,'定位真实异常样本');const d=done.result;closeOverlay();if(d.candidates?.length===1){await runInvestigation(d.candidates[0].selectionToken);return}openModal('选择实际要排查的一次请求',`<p>${esc(d.message)}</p><p class="small muted">${esc(d.timeResolution?.description)} · 已检索 ${d.timeResolution?.searchedWindows?.length||0} 个窗口</p>${d.possiblyTruncated||d.coveredFullRange===false?'<div class="warning-inline">当前仅展示有限候选，不代表完整时间范围。可以缩小发生时间窗口后重查。</div>':''}<div class="condition-grid">${(d.candidates||[]).map(row=>`<button class="condition-row candidate-choice" data-action="choose-live" data-token="${esc(row.selectionToken)}"><div class="row between"><strong>${esc(row.time)}</strong>${icon('arrow')}</div><p>${esc(row.platform)} · ${esc(row.bundle)} · ${esc(row.error||'HTTP '+row.status)}</p><p class="mono">${esc(row.traceId)}</p></button>`).join('')||'<p class="muted">没有取得可关联样本，不复用旧结果。</p>'}</div>`,`<button class="btn" data-action="close">返回补充时间</button>`,true)}catch(e){if(e.cancelled){toast(e.message);return}openModal('本次查询未完成',`<p>${esc(e.message)}</p><div class="warning-inline">失败状态已保留，未使用预置案例代替本次查询结果。</div>`,`<button class="btn" data-action="close">返回工作台</button><button class="btn" data-action="connections">检查数据源连接</button>`)}}
  async function runInvestigation(token){try{clearInterval(connectionTimer);const started=await api('investigate',{method:'POST',body:JSON.stringify({selectionToken:token})});const done=await waitJob(started.jobId,'关联这一次异常的真实证据');const entry=done.result.case;E.validate(entry.data);entry.data.collection.elapsedSeconds=done.elapsedSeconds;state.imported.push(entry);closeOverlay();setCase(entry.key);toast('在线采集完成 · '+entry.data.queries.length+' 次业务查询 · '+done.elapsedSeconds+' 秒')}catch(e){if(e.cancelled){toast(e.message);return}openModal('链路采集未完成',`<p>${esc(e.message)}</p><p>该状态不等同于没有异常或没有日志。请核对时间、账号权限和平台保留期。</p>`,`<button class="btn" data-action="close">返回</button>`)}}

  async function loadSavedCases(){try{const d=await api('cases');state.saved=d.cases||[];render()}catch{render()}}
  async function runSalvage(){try{await probe();if(!live.canQuery){await connectionModal();return}const started=await api('salvage',{method:'POST',body:JSON.stringify({traceId:state.data.incident.traceId,occurredAt:state.data.incident.occurredAt})});const done=await waitJob(started.jobId,'补查客户端日志');const entry=done.result.case;E.validate(entry.data);state.imported.push(entry);setCase(entry.key);state.tab='salvage';render();toast('Vesta 查询记录已更新')}catch(e){openModal('客户端回捞未完成',`<p>${esc(e.message)}</p><p>保留现有证据，不将查询失败解释为没有客户端日志。</p>`,`<button class="btn" data-action="close">返回</button>`)}}

  window.TraceAgentUI.init({api,render,toast});
  render();
  probe().then(d=>{if(d?.canQuery)loadSavedCases()});
})();
